const SITES = ['example-client.com'];

function fetchFull(url) {
  const https = require('https');
  return new Promise((resolve) => {
    let done = false; const finish = v => { if (!done) { done = true; resolve(v); } };
    const t0 = Date.now();
    const req = https.get(url, { timeout: 15000, headers: { 'User-Agent': 'ClientReporter' } }, (res) => {
      let data = ''; let bytes = 0;
      res.on('data', c => { bytes += c.length; if (data.length < 500000) data += c; });
      res.on('end', () => finish({ status: res.statusCode, body: data, bytes, loadMs: Date.now() - t0 }));
      res.on('close', () => finish({ status: res.statusCode || 0, body: data, bytes, loadMs: Date.now() - t0 }));
    });
    req.on('error', () => finish({ status: 0, body: '', bytes: 0, loadMs: Date.now() - t0 }));
    req.on('timeout', () => { req.destroy(); finish({ status: 0, body: '', bytes: 0, loadMs: Date.now() - t0 }); });
  });
}
function ping(url) {
  const https = require('https');
  return new Promise((resolve) => {
    let done = false; const finish = v => { if (!done) { done = true; resolve(v); } };
    const req = https.get(url, { timeout: 8000, headers: { 'User-Agent': 'ClientReporter' } }, (res) => { res.resume(); finish(res.statusCode); });
    req.on('error', () => finish(0)); req.on('timeout', () => { req.destroy(); finish(0); });
  });
}
function sslDaysLeft(host) {
  const tls = require('tls');
  return new Promise((resolve) => {
    let done = false; const finish = v => { if (!done) { done = true; resolve(v); } };
    const socket = tls.connect({ host, port: 443, servername: host, timeout: 8000 }, () => {
      const cert = socket.getPeerCertificate(); socket.end();
      finish(cert && cert.valid_to ? Math.round((new Date(cert.valid_to) - Date.now()) / 86400000) : null);
    });
    socket.on('error', () => finish(null)); socket.on('timeout', () => { socket.destroy(); finish(null); });
  });
}
function pagespeed(site) {
  let key = ''; try { key = ($env && $env.PAGESPEED_API_KEY) || ''; } catch (e) { key = ''; }
  if (!key) return Promise.resolve(null);
  const https = require('https');
  const url = 'https://www.googleapis.com/pagespeedonline/v5/runPagespeed?url=https://' + site + '&strategy=mobile&category=performance&category=seo&category=accessibility&category=best-practices&key=' + key;
  return new Promise((resolve) => {
    const req = https.get(url, { timeout: 60000 }, (res) => {
      let d = ''; res.on('data', c => d += c); res.on('end', () => {
        try { const j = JSON.parse(d); if (j.error) return resolve(null);
          const c = j.lighthouseResult.categories, a = j.lighthouseResult.audits;
          resolve({ performance: Math.round((c.performance?.score || 0) * 100), seo: Math.round((c.seo?.score || 0) * 100),
            accessibility: Math.round((c.accessibility?.score || 0) * 100), bestPractices: Math.round((c['best-practices']?.score || 0) * 100),
            lcp: a['largest-contentful-paint']?.displayValue, cls: a['cumulative-layout-shift']?.displayValue, tbt: a['total-blocking-time']?.displayValue });
        } catch (e) { resolve(null); }
      });
    });
    req.on('error', () => resolve(null)); req.on('timeout', () => { req.destroy(); resolve(null); });
  });
}

async function gather(site) {
  const home = await fetchFull('https://' + site);
  const html = home.body || '';
  const up = home.status >= 200 && home.status < 400;
  const title = ((html.match(/<title[^>]*>([^<]*)/i) || [])[1] || '').trim();
  const metaDesc = (html.match(/name=["']description["'][^>]*content=["']([^"']*)/i) || [])[1] || '';
  const h1s = (html.match(/<h1[\s>]/gi) || []).length;
  const hasViewport = /name=["']viewport["']/i.test(html);
  const sizeKb = Math.round(home.bytes / 1024);
  const ssl = up ? await sslDaysLeft(site) : null;
  const psi = up ? await pagespeed(site) : null;
  const robots = (await ping('https://' + site + '/robots.txt')) === 200;
  const sitemap = (await ping('https://' + site + '/sitemap.xml')) === 200 || (await ping('https://' + site + '/sitemap_index.xml')) === 200;
  return { site, up, status: home.status, loadMs: home.loadMs, sizeKb, sslDays: ssl,
    psi,
    seo: { title, titleLen: title.length, metaDesc, metaLen: metaDesc.length, h1s, hasViewport, robots, sitemap } };
}
async function main() {
  const out = [];
  for (const s of SITES) out.push({ json: await gather(s) });
  return out;
}
return main();

const RECIPIENTS = { 'example-client.com': 'alerts@yourdomain.com' }; // set each client's email here (defaults to you for review)

function claude(prompt) {
  const https = require('https');
  const key = $env.ANTHROPIC_API_KEY;
  if (!key) return Promise.resolve(null);
  const payload = JSON.stringify({ model: 'claude-opus-4-8', max_tokens: 700, messages: [{ role: 'user', content: prompt }] });
  return new Promise((resolve) => {
    const req = https.request('https://api.anthropic.com/v1/messages',
      { method: 'POST', timeout: 40000, headers: { 'content-type': 'application/json', 'x-api-key': key, 'anthropic-version': '2023-06-01' } }, (res) => {
        let d = ''; res.on('data', c => d += c); res.on('end', () => { try { const j = JSON.parse(d); resolve(j.content?.[0]?.text?.trim() || null); } catch (e) { resolve(null); } });
      });
    req.on('error', () => resolve(null)); req.on('timeout', () => { req.destroy(); resolve(null); });
    req.write(payload); req.end();
  });
}
function gemini(prompt) {
  const https = require('https');
  const key = $env.GEMINI_API_KEY;
  if (!key) return Promise.resolve(null);
  const payload = JSON.stringify({ contents: [{ parts: [{ text: prompt }] }], generationConfig: { maxOutputTokens: 700, temperature: 0.5 } });
  return new Promise((resolve) => {
    const req = https.request('https://generativelanguage.googleapis.com/v1beta/models/gemini-2.0-flash-lite:generateContent?key=' + key,
      { method: 'POST', timeout: 30000, headers: { 'content-type': 'application/json' } }, (res) => {
        let d = ''; res.on('data', c => d += c); res.on('end', () => { try { const j = JSON.parse(d); resolve(j.candidates?.[0]?.content?.parts?.[0]?.text?.trim() || null); } catch (e) { resolve(null); } });
      });
    req.on('error', () => resolve(null)); req.on('timeout', () => { req.destroy(); resolve(null); });
    req.write(payload); req.end();
  });
}
async function llm(prompt) { return (await claude(prompt)) || (await gemini(prompt)) || '(report unavailable — check ANTHROPIC_API_KEY / GEMINI_API_KEY)'; }

function buildPrompt(m) {
  return 'You are writing a short, friendly MONTHLY website health report for a non-technical client who owns ' + m.site + '.\n' +
    'Write 150-200 words in plain English (no jargon; explain any number simply). Structure: a one-line overall verdict, 2-3 things that are good, 1-2 things to improve, and one clear recommendation for this month. Encouraging but honest.\n\n' +
    'Data:\n- Reachable: ' + m.up + ' (HTTP ' + m.status + ')\n- Homepage load time: ' + m.loadMs + ' ms\n- Page size: ' + m.sizeKb + ' KB\n- SSL certificate: ' + (m.sslDays == null ? 'unknown' : m.sslDays + ' days until expiry') + '\n- SEO: title "' + m.seo.title + '" (' + m.seo.titleLen + ' chars), meta description ' + m.seo.metaLen + ' chars, ' + m.seo.h1s + ' H1 heading(s), mobile viewport: ' + m.seo.hasViewport + ', robots.txt: ' + m.seo.robots + ', sitemap: ' + m.seo.sitemap + (m.psi ? '\n- PageSpeed (mobile, 0-100): performance ' + m.psi.performance + ', SEO ' + m.psi.seo + ', accessibility ' + m.psi.accessibility + ', best-practices ' + m.psi.bestPractices + '; LCP ' + m.psi.lcp + ', CLS ' + m.psi.cls + ', TBT ' + m.psi.tbt : '') +
    '\n\nWrite only the report, no preamble.';
}
async function main() {
  const out = [];
  for (const item of items) {
    const m = item.json;
    const report = await llm(buildPrompt(m));
    const to = RECIPIENTS[m.site] || 'alerts@yourdomain.com';
    const subject = '📊 Monthly site report — ' + m.site;
    const footer = '\n\n———\nAt a glance: ' + (m.up ? 'online' : 'OFFLINE') + ' · load ' + m.loadMs + 'ms · ' + m.sizeKb + 'KB · SSL ' + (m.sslDays == null ? '?' : m.sslDays + 'd left') +
      ' · SEO ' + (m.seo.title ? 'title✓' : 'title✗') + ' ' + (m.seo.metaDesc ? 'meta✓' : 'meta✗') + ' ' + (m.seo.sitemap ? 'sitemap✓' : 'sitemap✗') + (m.psi ? ' · PageSpeed ' + m.psi.performance + '/100' : '');
    const text = report + footer + '\n\nGenerated automatically on ' + new Date().toISOString().slice(0, 10) + '.';
    out.push({ json: { site: m.site, to, subject, text } });
  }
  return out;
}
return main();
